//
//  SwiftForgeTheme+Paper.swift
//  SwiftForgeUI
//
//  Colors are generated by scripts/theme-design (see docs/design/themes/paper.md)
//  and verified by SwiftForgeContrastAudit in every test run.
//

import SwiftUI

extension SwiftForgeTheme {

    /// Minimal and editorial: ink on warm paper, serif headings set in New
    /// York, hairlines everywhere, and no shadows at all.
    ///
    /// The accent is the ink itself — black on paper, flipping to off-white
    /// in dark mode — so color is reserved for status. Corners are barely
    /// rounded (3-pt controls, 4-pt cards), text fields are underlined, and
    /// nothing scales when pressed.
    public static let paper: SwiftForgeTheme = {
        typealias P = Palette.Paper
        let accent = SwiftForgeToneColors(
            solid: SwiftForgeColor(
                light: P.ink, dark: P.chalk, lightHighContrast: Palette.black, darkHighContrast: Palette.white),
            onSolid: SwiftForgeColor(
                light: P.paper, dark: P.night, lightHighContrast: Palette.white, darkHighContrast: Palette.black),
            text: SwiftForgeColor(light: P.ink, dark: P.chalk, lightHighContrast: Palette.black, darkHighContrast: Palette.white),
            subtle: SwiftForgeColor(
                light: P.Stone.s100, dark: P.Stone.s900, lightHighContrast: P.Stone.s200, darkHighContrast: P.Stone.s800)
        )
        let colors = SwiftForgeColors(
            canvas: SwiftForgeColor(light: P.paper, dark: P.night),
            surface: SwiftForgeColor(light: P.sheet, dark: P.nightSheet),
            surfaceRaised: SwiftForgeColor(light: Palette.white, dark: P.nightLift),
            fillMuted: SwiftForgeColor(
                light: P.Stone.s100, dark: P.Stone.s900, lightHighContrast: P.Stone.s200, darkHighContrast: P.Stone.s800),
            textPrimary: SwiftForgeColor(
                light: P.ink, dark: P.chalk, lightHighContrast: Palette.black, darkHighContrast: Palette.white),
            textSecondary: SwiftForgeColor(
                light: P.Stone.s700, dark: P.Stone.s300, lightHighContrast: P.Stone.s800, darkHighContrast: P.Stone.s200),
            borderSubtle: SwiftForgeColor(
                light: P.Stone.s200, dark: P.Stone.s800, lightHighContrast: P.Stone.s400, darkHighContrast: P.Stone.s600),
            borderStrong: SwiftForgeColor(
                light: P.Stone.s500, dark: P.Stone.s500, lightHighContrast: P.Stone.s700, darkHighContrast: P.Stone.s300),
            focusRing: accent.text,
            pressedOverlay: SharedTokens.pressedOverlay,
            accent: accent,
            neutral: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Stone.s700, dark: P.Stone.s300, lightHighContrast: P.Stone.s800, darkHighContrast: P.Stone.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.night, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Stone.s700, dark: P.Stone.s300, lightHighContrast: P.Stone.s800, darkHighContrast: P.Stone.s200),
                subtle: SwiftForgeColor(
                    light: P.Stone.s100, dark: P.Stone.s900, lightHighContrast: P.Stone.s200, darkHighContrast: P.Stone.s800)
            ),
            info: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Indigo.s700, dark: P.Indigo.s300, lightHighContrast: P.Indigo.s800, darkHighContrast: P.Indigo.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.night, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Indigo.s700, dark: P.Indigo.s300, lightHighContrast: P.Indigo.s800, darkHighContrast: P.Indigo.s200),
                subtle: SwiftForgeColor(
                    light: P.Indigo.s50, dark: P.Indigo.s950, lightHighContrast: P.Indigo.s100, darkHighContrast: P.Indigo.s900)
            ),
            success: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Forest.s700, dark: P.Forest.s300, lightHighContrast: P.Forest.s800, darkHighContrast: P.Forest.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.night, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Forest.s700, dark: P.Forest.s300, lightHighContrast: P.Forest.s800, darkHighContrast: P.Forest.s200),
                subtle: SwiftForgeColor(
                    light: P.Forest.s50, dark: P.Forest.s950, lightHighContrast: P.Forest.s100, darkHighContrast: P.Forest.s900)
            ),
            warning: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Ochre.s300, dark: P.Ochre.s300, lightHighContrast: P.Ochre.s400, darkHighContrast: P.Ochre.s200),
                onSolid: SwiftForgeColor(
                    light: P.ink, dark: P.night, lightHighContrast: Palette.black, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Ochre.s700, dark: P.Ochre.s300, lightHighContrast: P.Ochre.s800, darkHighContrast: P.Ochre.s200),
                subtle: SwiftForgeColor(
                    light: P.Ochre.s50, dark: P.Ochre.s950, lightHighContrast: P.Ochre.s100, darkHighContrast: P.Ochre.s900)
            ),
            danger: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Oxblood.s700, dark: P.Oxblood.s300, lightHighContrast: P.Oxblood.s800,
                    darkHighContrast: P.Oxblood.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.night, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Oxblood.s700, dark: P.Oxblood.s300, lightHighContrast: P.Oxblood.s800,
                    darkHighContrast: P.Oxblood.s200),
                subtle: SwiftForgeColor(
                    light: P.Oxblood.s50, dark: P.Oxblood.s950, lightHighContrast: P.Oxblood.s100,
                    darkHighContrast: P.Oxblood.s900)
            )
        )
        let typography = SwiftForgeTypography.standard.updating(SwiftForgeTypography.displayRoles) { $0.design = .serif }
        return SwiftForgeTheme(
            id: "paper",
            displayName: "Paper",
            colors: colors,
            typography: typography,
            radius: SwiftForgeRadius(
                xs: 0, sm: 2, md: 3, lg: 4, xl: 6, xxl: 8,
                control: 3, controlSmall: 2, card: 4, sheet: 8
            ),
            elevation: SharedTokens.flat,
            motion: SwiftForgeMotion(
                fast: SwiftForgeMotionToken(duration: 0.2),
                standard: SwiftForgeMotionToken(duration: 0.3),
                emphasized: SwiftForgeMotionToken(duration: 0.4),
                shimmerDuration: 1.6,
                pressedScale: 1
            ),
            components: SwiftForgeComponentTokens(
                button: SwiftForgeButtonTokens(pressEffect: .scale(1)),
                card: SwiftForgeCardTokens(pressEffect: .scale(1)),
                surface: SwiftForgeSurfaceTokens(bordersEverySurface: true),
                field: SwiftForgeFieldTokens(style: .underlined),
                toggle: SwiftForgeToggleTokens(cornerRadius: 4),
                badge: SwiftForgeBadgeTokens(cornerRadius: 2, borderWidth: 1),
                banner: SwiftForgeBannerTokens(borderWidth: 1, title: typography.subheadline.weight(.semibold).designed(.serif)),
                progress: SwiftForgeProgressTokens(
                    barHeight: 2, barHeightLarge: 4, barCornerRadius: 0, ringLineWidth: 2, ringLineWidthLarge: 3),
                selectionControl: SwiftForgeSelectionControlTokens(borderWidth: 1),
                segmentedControl: SwiftForgeSegmentedControlTokens(borderWidth: 1),
                slider: SwiftForgeSliderTokens(trackHeight: 2, thumbDiameter: 20),
                avatar: SwiftForgeAvatarTokens(borderWidth: 1)
            )
        )
    }()
}
